import 'package:hiddify/hiddifycore/generated/v2/hcore/hcore.pb.dart';

/// Builds a sanitized report using stable IDs embedded in candidate node tags.
///
/// Candidate nodes must be named with the prefix
/// `probe_<24 lowercase hex chars>__`. The ID is generated by AutoSubHub
/// from the canonical proxy configuration and remains stable between builds.
/// Raw tags, server addresses, credentials, and proxy URIs are never uploaded.
class DomesticProbeReportBuilder {
  static final RegExp _candidateTag = RegExp(r'^probe_([a-f0-9]{24})__');

  Map<String, dynamic> build({
    required List<OutboundInfo> outbounds,
    int maxNodes = 50,
    DateTime? testedAt,
  }) {
    if (maxNodes < 1 || maxNodes > 50) {
      throw ArgumentError.value(maxNodes, 'maxNodes', 'Must be between 1 and 50');
    }

    final candidates = outbounds
        .where((item) =>
            !item.isGroup &&
            item.isVisible &&
            !item.tag.contains('§hide§') &&
            _candidateTag.hasMatch(item.tag))
        .take(maxNodes)
        .toList(growable: false);

    if (candidates.isEmpty) {
      throw StateError('No visible AutoSubHub candidate nodes are available');
    }

    final ids = <String>{};
    final results = candidates.map((item) {
      final match = _candidateTag.firstMatch(item.tag)!;
      final nodeId = 'probe_${match.group(1)}';
      if (!ids.add(nodeId)) {
        throw StateError('Duplicate stable candidate node ID: $nodeId');
      }

      final bytesPerSecond = item.downloadSpeed.toInt();
      final isFresh = !item.downloadSpeedCached;
      final status = !isFresh || bytesPerSecond == 0
          ? 'inconclusive'
          : bytesPerSecond > 0
              ? 'passed'
              : 'failed';
      final latency = item.urlTestDelay > 0 && item.urlTestDelay < 65000
          ? item.urlTestDelay
          : null;

      return <String, dynamic>{
        'node_id': nodeId,
        'protocol': _protocolOf(item.type),
        'status': status,
        'download_kbps': status == 'passed' ? bytesPerSecond * 8 / 1000 : null,
        'latency_ms': latency,
        'gpt_ok': null,
      };
    }).toList(growable: false);

    return {
      'device_id': 'mi6-probe-01',
      'network': 'mainland-wifi',
      'tested_at': (testedAt ?? DateTime.now()).toUtc().toIso8601String(),
      'results': results,
    };
  }

  static String _protocolOf(String type) {
    final value = type.toLowerCase();
    if (value.contains('shadowsocks') || value == 'ss') return 'shadowsocks';
    if (value.contains('vmess')) return 'vmess';
    if (value.contains('vless')) return 'vless';
    if (value.contains('trojan')) return 'trojan';
    if (value.contains('hysteria2') || value.contains('hysteria 2')) return 'hysteria2';
    if (value.contains('tuic')) return 'tuic';
    return 'other';
  }
}
